/**
 * generated by stackra gen from src/config/env.config.ts (server fields), src/config/edge.config.ts
 * (redirects, redirectCacheSeconds, notFoundLog), src/config/csp.config.ts, runway.yaml (aliases)
 * and assets/lang/{en,ar}/web.json (errors.server) — do not edit
 * Purpose: the Cloudflare Worker entry: refuses malformed requests, redirects an alias host to the
 *          canonical domain and a `//` path to its single-slash form, mints the request's CSP
 *          nonce, hands the request to the React Router server build with `{ env, ctx, app, nonce,
 *          clients }` as the load context, sets the CSP header, and only when the router answers an
 *          HTML 404 asks the experience `seo` module for a redirect (failing open, same-site
 *          targets only) or records the 404 after the response is sent.
 * Boundary: config classes are resolved from the app's container, never read as statics; the CSP
 *           baseline is @stackra/csp's and the config only adds sources. A throw anywhere becomes
 *           a static 500 page after it reaches the reporter; nothing a request sends can crash the
 *           isolate. A GET HTML response never sets a cookie (the route modules own that rule; the
 *           e2e tier asserts it).
 * Runtime: worker
 */
import { createRequestHandler } from "react-router";
import { contentSecurityPolicy, cspHeaderName, createNonce } from "@stackra/csp";
import { publicClients } from "#stackra/clients.server";
import { Experience } from "#stackra/clients";
import { serverEnv } from "#stackra/env";
import type { WebEnv } from "#src/config/env.config";
import { CspConfig } from "#src/config/csp.config";
import { EdgeConfig } from "#src/config/edge.config";
import { app } from "../app";

const requestHandler = createRequestHandler(
  () => import("virtual:react-router/server-build"),
  import.meta.env.MODE,
);

/** The page a crash answers with: static, bilingual, no script, never cached. */
const CRASH_PAGE = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport"
content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>Something
went wrong</title></head><body><main><h1>Something went wrong</h1><p>We have been told. Please try
again in a moment.</p><section lang="ar" dir="rtl"><h1>حدث خطأ ما</h1><p>تم إبلاغنا. يرجى المحاولة
بعد قليل.</p></section></main></body></html>`;

/** A redirect the experience `seo` module answered, or `null` for none. */
type SeoRedirect = { readonly to: string; readonly status: 301 | 302 } | null;

/** Only navigations are redirected or logged; asset and data requests pass straight through. */
function isHtmlNavigation(request: Request): boolean {
  return request.method === "GET" && (request.headers.get("accept") ?? "").includes("text/html");
}

/** The router's answer, then the redirect lookup and the 404 log for an HTML 404. */
async function handle(request: Request, rawEnv: Env, ctx: ExecutionContext): Promise<Response> {
  if ((request.method === "GET" || request.method === "HEAD") && request.body !== null) {
    return new Response(null, { status: 400 });
  }
  const env = serverEnv(rawEnv); // a missing var fails here with a typed error naming it
  const url = new URL(request.url);
  const canonical = new URL(env.siteUrl);
  if (url.host !== canonical.host && !url.host.startsWith("localhost")) {
    return Response.redirect(new URL(url.pathname + url.search, canonical).toString(), 301);
  }
  if (url.pathname.includes("//")) {
    const single = url.pathname.replace(/\/{2,}/g, "/");
    return Response.redirect(new URL(single + url.search, url.origin).toString(), 301);
  }

  const nonce = createNonce(); // 128 bits from crypto.getRandomValues, base64
  const csp = app.container.resolve(CspConfig);
  const response = await requestHandler(request, {
    env,
    ctx,
    app,
    nonce,
    clients: (options) => publicClients(env, options),
  });
  response.headers.set(
    cspHeaderName(csp),
    contentSecurityPolicy(csp, { connect: [env.apiUrl], nonce }),
  );
  if (response.status !== 404 || !isHtmlNavigation(request)) return response;

  const edge = app.container.resolve(EdgeConfig);
  const redirect = edge.lookupRedirects ? await lookupRedirect(url, env, ctx, edge) : null;
  if (redirect) return Response.redirect(redirect.href, redirect.status);
  if (edge.notFoundLog) {
    const referrer = request.headers.get("referer") ?? undefined;
    ctx.waitUntil(
      publicClients(env).queue(Experience.actions.RecordNotFound, {
        host: url.host,
        path: url.pathname,
        referrer,
      }),
    );
  }
  return response;
}

/**
 * The experience `seo` module's redirect for a path the router does not know, edge-cached for
 * `redirectCacheSeconds`. Fails open: a lookup error keeps the 404 page. A target on another site
 * is refused, so a tenant's redirect table can never send visitors off the site.
 */
async function lookupRedirect(
  url: URL,
  env: WebEnv,
  ctx: ExecutionContext,
  edge: EdgeConfig,
): Promise<{ href: string; status: 301 | 302 } | null> {
  try {
    const cache = caches.default;
    const key = new Request(`${url.origin}/__redirect${url.pathname.toLowerCase()}`);
    let cached = await cache.match(key);
    if (!cached) {
      const answer = await publicClients(env).query(Experience.queries.ResolveRedirect, {
        host: url.host,
        path: url.pathname,
      });
      cached = Response.json(answer, {
        headers: { "Cache-Control": `max-age=${edge.redirectCacheSeconds}` },
      });
      ctx.waitUntil(cache.put(key, cached.clone()));
    }
    const redirect = (await cached.json()) as SeoRedirect;
    if (!redirect) return null;
    const target = new URL(redirect.to, url);
    if (target.origin !== url.origin) return null;
    return { href: target.toString(), status: redirect.status };
  } catch (error) {
    app.reporter.report(error);
    return null;
  }
}

export default {
  async fetch(request, rawEnv, ctx) {
    try {
      return await handle(request, rawEnv, ctx);
    } catch (error) {
      app.reporter.report(error);
      return new Response(CRASH_PAGE, {
        status: 500,
        headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" },
      });
    }
  },
} satisfies ExportedHandler<Env>;
